{"tool":"newFileCreated","path":"css/styles.css","content":"/* ==================== BASE STYLES ==================== */
* {
    box-sizing: border-box;
    -webkit-tap-highlight-color: transparent;
}

html {
    scroll-behavior: smooth;
}

body {
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Oxygen, Ubuntu, Cantarell, sans-serif;
    -webkit-font-smoothing: antialiased;
    -moz-osx-font-smoothing: grayscale;
}

/* Prevent zoom on input focus (iOS) */
input, select, textarea {
    font-size: 16px !important;
}

/* ==================== SCREEN TRANSITIONS ==================== */
.screen {
    transition: opacity 0.3s ease-in-out;
}

.screen.hidden {
    display: none !important;
}

.screen.fade-out {
    opacity: 0;
}

.screen.fade-in {
    opacity: 1;
}

/* ==================== GLITCH EFFECT ==================== */
.glitch-container {
    position: relative;
}

.glitch-text {
    position: relative;
    animation: glitch-skew 1s infinite linear alternate-reverse;
}

.glitch-text::before,
.glitch-text::after {
    content: attr(data-text);
    position: absolute;
    top: 0;
    left: 0;
    width: 100%;
    height: 100%;
}

.glitch-text::before {
    left: 2px;
    text-shadow: -2px 0 #ff3333;
    clip: rect(24px, 550px, 90px, 0);
    animation: glitch-anim 2s infinite linear alternate-reverse;
}

.glitch-text::after {
    left: -2px;
    text-shadow: -2px 0 #00ff88;
    clip: rect(85px, 550px, 140px, 0);
    animation: glitch-anim2 2s infinite linear alternate-reverse;
}

@keyframes glitch-anim {
    0% { clip: rect(31px, 9999px, 94px, 0); }
    5% { clip: rect(70px, 9999px, 71px, 0); }
    10% { clip: rect(29px, 9999px, 24px, 0); }
    15% { clip: rect(3px, 9999px, 54px, 0); }
    20% { clip: rect(39px, 9999px, 98px, 0); }
    25% { clip: rect(17px, 9999px, 73px, 0); }
    30% { clip: rect(67px, 9999px, 96px, 0); }
    35% { clip: rect(4px, 9999px, 31px, 0); }
    40% { clip: rect(95px, 9999px, 35px, 0); }
    45% { clip: rect(11px, 9999px, 29px, 0); }
    50% { clip: rect(67px, 9999px, 62px, 0); }
    55% { clip: rect(98px, 9999px, 10px, 0); }
    60% { clip: rect(42px, 9999px, 97px, 0); }
    65% { clip: rect(79px, 9999px, 68px, 0); }
    70% { clip: rect(13px, 9999px, 86px, 0); }
    75% { clip: rect(33px, 9999px, 41px, 0); }
    80% { clip: rect(45px, 9999px, 16px, 0); }
    85% { clip: rect(2px, 9999px, 91px, 0); }
    90% { clip: rect(56px, 9999px, 78px, 0); }
    95% { clip: rect(89px, 9999px, 5px, 0); }
    100% { clip: rect(31px, 9999px, 55px, 0); }
}

@keyframes glitch-anim2 {
    0% { clip: rect(65px, 9999px, 100px, 0); }
    5% { clip: rect(52px, 9999px, 74px, 0); }
    10% { clip: rect(79px, 9999px, 85px, 0); }
    15% { clip: rect(75px, 9999px, 5px, 0); }
    20% { clip: rect(67px, 9999px, 61px, 0); }
    25% { clip: rect(14px, 9999px, 79px, 0); }
    30% { clip: rect(1px, 9999px, 66px, 0); }
    35% { clip: rect(86px, 9999px, 30px, 0); }
    40% { clip: rect(23px, 9999px, 98px, 0); }
    45% { clip: rect(85px, 9999px, 72px, 0); }
    50% { clip: rect(71px, 9999px, 75px, 0); }
    55% { clip: rect(2px, 9999px, 48px, 0); }
    60% { clip: rect(30px, 9999px, 16px, 0); }
    65% { clip: rect(59px, 9999px, 50px, 0); }
    70% { clip: rect(41px, 9999px, 62px, 0); }
    75% { clip: rect(2px, 9999px, 82px, 0); }
    80% { clip: rect(47px, 9999px, 73px, 0); }
    85% { clip: rect(3px, 9999px, 27px, 0); }
    90% { clip: rect(26px, 9999px, 55px, 0); }
    95% { clip: rect(42px, 9999px, 97px, 0); }
    100% { clip: rect(38px, 9999px, 49px, 0); }
}

@keyframes glitch-skew {
    0% { transform: skew(0deg); }
    20% { transform: skew(0deg); }
    21% { transform: skew(2deg); }
    22% { transform: skew(0deg); }
    60% { transform: skew(0deg); }
    61% { transform: skew(-1deg); }
    62% { transform: skew(0deg); }
    100% { transform: skew(0deg); }
}

/* ==================== SHAKE EFFECT ==================== */
@keyframes shake {
    0%, 100% { transform: translateX(0); }
    10% { transform: translateX(-10px); }
    20% { transform: translateX(10px); }
    30% { transform: translateX(-10px); }
    40% { transform: translateX(10px); }
    50% { transform: translateX(-5px); }
    60% { transform: translateX(5px); }
    70% { transform: translateX(-5px); }
    80% { transform: translateX(5px); }
    90% { transform: translateX(-2px); }
}

.shake {
    animation: shake 0.5s ease-in-out;
}

/* ==================== SUCCESS FLASH ==================== */
@keyframes success-flash {
    0% { background-color: rgba(0, 255, 136, 0); }
    50% { background-color: rgba(0, 255, 136, 0.3); }
    100% { background-color: rgba(0, 255, 136, 0); }
}

.success-flash {
    animation: success-flash 0.5s ease-out;
}

/* ==================== ERROR FLASH ==================== */
@keyframes error-flash {
    0% { background-color: rgba(255, 51, 51, 0); }
    50% { background-color: rgba(255, 51, 51, 0.3); }
    100% { background-color: rgba(255, 51, 51, 0); }
}

.error-flash {
    animation: error-flash 0.5s ease-out;
}

/* ==================== PULSE BORDER ==================== */
@keyframes pulse-border {
    0%, 100% { border-color: rgba(0, 255, 136, 0.3); }
    50% { border-color: rgba(0, 255, 136, 0.8); }
}

.pulse-border {
    animation: pulse-border 2s infinite;
}

/* ==================== TIMER WARNING ==================== */
.timer-warning {
    color: #ff3333 !important;
    animation: timer-pulse 0.5s infinite alternate;
}

@keyframes timer-pulse {
    0% { opacity: 1; }
    100% { opacity: 0.5; }
}

/* ==================== TYPEWRITER CURSOR ==================== */
.typed-cursor {
    color: #00ff88;
    font-weight: 100;
    animation: blink 0.7s infinite;
}

@keyframes blink {
    0%, 100% { opacity: 1; }
    50% { opacity: 0; }
}

/* ==================== CELEBRATION ==================== */
.celebration-container {
    animation: celebration-bounce 1s ease infinite;
}

@keyframes celebration-bounce {
    0%, 100% { transform: scale(1); }
    50% { transform: scale(1.2); }
}

/* Confetti container */
.confetti-container {
    position: fixed;
    top: 0;
    left: 0;
    width: 100%;
    height: 100%;
    pointer-events: none;
    overflow: hidden;
    z-index: 1000;
}

.confetti {
    position: absolute;
    width: 10px;
    height: 10px;
    animation: confetti-fall 3s ease-out forwards;
}

@keyframes confetti-fall {
    0% {
        transform: translateY(-100%) rotate(0deg);
        opacity: 1;
    }
    100% {
        transform: translateY(100vh) rotate(720deg);
        opacity: 0;
    }
}

/* ==================== COUNTDOWN ==================== */
@keyframes countdown-pop {
    0% { transform: scale(0.5); opacity: 0; }
    50% { transform: scale(1.2); opacity: 1; }
    100% { transform: scale(1); opacity: 1; }
}

.countdown-pop {
    animation: countdown-pop 0.5s ease-out;
}

/* ==================== DRAFT ANIMATION ==================== */
@keyframes slide-in-left {
    0% { transform: translateX(-100%); opacity: 0; }
    100% { transform: translateX(0); opacity: 1; }
}

@keyframes slide-in-right {
    0% { transform: translateX(100%); opacity: 0; }
    100% { transform: translateX(0); opacity: 1; }
}

.slide-in-left {
    animation: slide-in-left 0.5s ease-out forwards;
}

.slide-in-right {
    animation: slide-in-right 0.5s ease-out forwards;
}

/* ==================== EVIDENCE ITEM ==================== */
.evidence-item {
    padding: 8px 12px;
    background: rgba(0, 255, 136, 0.1);
    border-left: 3px solid #00ff88;
    border-radius: 0 4px 4px 0;
    animation: evidence-appear 0.3s ease-out;
}

@keyframes evidence-appear {
    0% { transform: translateX(-20px); opacity: 0; }
    100% { transform: translateX(0); opacity: 1; }
}

/* ==================== HINT BUTTON ==================== */
.hint-button {
    position: relative;
    overflow: hidden;
}

.hint-button::after {
    content: '';
    position: absolute;
    top: 0;
    left: -100%;
    width: 100%;
    height: 100%;
    background: linear-gradient(90deg, transparent, rgba(255, 255, 255, 0.2), transparent);
    animation: shimmer 2s infinite;
}

@keyframes shimmer {
    0% { left: -100%; }
    100% { left: 100%; }
}

/* ==================== PENALTY ANIMATION ==================== */
@keyframes penalty-flash {
    0% { color: white; }
    25% { color: #ff3333; }
    50% { color: white; }
    75% { color: #ff3333; }
    100% { color: white; }
}

.penalty-flash {
    animation: penalty-flash 0.5s ease-out;
}

/* ==================== SCROLLBAR ==================== */
::-webkit-scrollbar {
    width: 6px;
}

::-webkit-scrollbar-track {
    background: #1a1a1a;
}

::-webkit-scrollbar-thumb {
    background: #333;
    border-radius: 3px;
}

::-webkit-scrollbar-thumb:hover {
    background: #555;
}

/* ==================== MOBILE OPTIMIZATIONS ==================== */
@media (max-width: 600px) {
    /* Ensure touch targets are at least 44x44px */
    button, 
    input[type="text"], 
    .touch-target {
        min-height: 44px;
    }

    /* Prevent text selection on buttons */
    button {
        -webkit-user-select: none;
        user-select: none;
    }
}

/* ==================== LOADING SPINNER ==================== */
.spinner {
    width: 40px;
    height: 40px;
    border: 3px solid rgba(0, 255, 136, 0.3);
    border-top-color: #00ff88;
    border-radius: 50%;
    animation: spin 1s linear infinite;
}

@keyframes spin {
    to { transform: rotate(360deg); }
}

/* ==================== FOCUS STATES ==================== */
button:focus-visible,
input:focus-visible {
    outline: 2px solid #00ff88;
    outline-offset: 2px;
}

/* ==================== TERMINAL TYPING ==================== */
.terminal-line {
    overflow: hidden;
    white-space: nowrap;
    animation: typing 0.5s steps(20) forwards;
}

@keyframes typing {
    from { width: 0; }
    to { width: 100%; }
}

/* ==================== TEAM READY STATE ==================== */
[data-ready="true"] {
    background: linear-gradient(135deg, rgba(0, 255, 136, 0.3), rgba(0, 255, 136, 0.1)) !important;
    border-color: #00ff88 !important;
}

/* ==================== QR CODE STYLING ==================== */
#qr-code {
    background: white;
    padding: 10px;
    border-radius: 8px;
}

/* ==================== PHOTO PREVIEW ==================== */
#photo-preview {
    max-height: 300px;
    object-fit: contain;
}

/* ==================== SKIP PUZZLE MODAL ==================== */
.modal-overlay {
    position: fixed;
    inset: 0;
    background: rgba(0, 0, 0, 0.8);
    display: flex;
    align-items: center;
    justify-content: center;
    z-index: 100;
    animation: fade-in 0.2s ease-out;
}

@keyframes fade-in {
    from { opacity: 0; }
    to { opacity: 1; }
}

.modal-content {
    background: #1a1a1a;
    border: 1px solid #333;
    border-radius: 12px;
    padding: 24px;
    max-width: 320px;
    width: 90%;
    animation: modal-pop 0.3s ease-out;
}

@keyframes modal-pop {
    from { transform: scale(0.9); opacity: 0; }
    to { transform: scale(1); opacity: 1; }
}

/* ==================== TIMER DEDUCTION ANIMATION ==================== */
.timer-deduct {
    position: absolute;
    color: #ff3333;
    font-family: monospace;
    font-weight: bold;
    animation: float-up 1s ease-out forwards;
    pointer-events: none;
}

@keyframes float-up {
    0% { 
        transform: translateY(0); 
        opacity: 1; 
    }
    100% { 
        transform: translateY(-30px); 
        opacity: 0; 
    }
}

/* ==================== THIEF MESSAGE PANEL GLOW ==================== */
#thief-message-panel {
    transition: box-shadow 0.3s ease;
}

#thief-message-panel.active {
    box-shadow: 0 0 20px rgba(0, 255, 136, 0.2);
}

/* ==================== DARK OVERLAY FOR MODALS ==================== */
.dark-overlay {
    position: fixed;
    inset: 0;
    background: rgba(0, 0, 0, 0.9);
    z-index: 50;
}

/* ==================== HINT REVEAL ==================== */
.hint-text {
    background: linear-gradient(90deg, #ff3333, #ff6666);
    -webkit-background-clip: text;
    -webkit-text-fill-color: transparent;
    background-clip: text;
}

/* ==================== BRUTE FORCE WARNING ==================== */
.brute-force-warning {
    background: linear-gradient(135deg, rgba(255, 51, 51, 0.2), transparent);
    border: 1px solid #ff3333;
    border-radius: 8px;
    padding: 12px;
    animation: warning-pulse 2s infinite;
}

@keyframes warning-pulse {
    0%, 100% { border-color: rgba(255, 51, 51, 0.5); }
    50% { border-color: rgba(255, 51, 51, 1); }
