function loadState() {
    try {
        const saved = localStorage.getItem('caseFile7734');
        if (saved) {
            const data = JSON.parse(saved);
            // Check if save is from a recent session (within 24 hours)
            if (Date.now() - data.savedAt < 24 * 60 * 60 * 1000) {
                gameState = { ...gameState, ...data };
                return true;
            }
        }
    } catch (e) {
