            document.getElementById('app').classList.add('shake');
            
            // Offer hint after many attempts
            if (attemptCount >= 5) {
                showHintOffer();
            }
            
            // Offer skip after 10 attempts
            if (attemptCount >= 10) {
                showSkipOffer();
            }
            
        } else {
            // First wrong - just a taunt
            showAnswerFeedback('wrong', taunt);
        }
    }
    
    input.value = '';
    input.focus();
}

