            const pick = allPicks[pickIndex];
            const li = document.createElement('li');
            li.textContent = pick.player.name + (pick.player.captain ? ' 👑' : '');
            li.className = pick.team === 1 ? 'text-blue-300 slide-in-left' : 'text-pink-300 slide-in-right';
            
