    const windowStart = now - CONFIG.RATE_LIMIT.WINDOW * 1000;
    gameState.recentAttempts = gameState.recentAttempts.filter(t => t > windowStart);
}

function recordAttempt() {
    const now = Date.now();
    gameState.recentAttempts.push(now);
    
