    spacer.style.marginTop = '1.5rem';
    terminalContent.appendChild(spacer);
    terminalContent.appendChild(messageContainer);
    
    // Reset message index
    currentMessageIndex = 0;
    
    // Show first message
    showThiefIntroMessage(messageContainer, beginButton);
}

