/* ==================== ANIMATIONS ==================== */
@keyframes shake {
    0%, 100% { transform: translateX(0); }
    10%, 30%, 50%, 70%, 90% { transform: translateX(-5px); }
    20%, 40%, 60%, 80% { transform: translateX(5px); }
}

.shake {
    animation: shake 0.5s ease-in-out;
}

@keyframes successFlash {
    0% { box-shadow: 0 0 0 0 rgba(16, 185, 129, 0.5); }
    100% { box-shadow: 0 0 0 20px rgba(16, 185, 129, 0); }
}

.success-flash {
    animation: successFlash 0.5s ease-out;
}

/* Glitch effect */
.glitch-text {
    position: relative;
    animation: glitchSkew 1s infinite linear alternate-reverse;
}

@keyframes glitchSkew {
    0%, 80% { transform: skew(0deg); }
    85% { transform: skew(2deg); }
    90% { transform: skew(-1deg); }
    95% { transform: skew(1deg); }
    100% { transform: skew(0deg); }
}

/* Typewriter cursor */
.typed-cursor {
    color: var(--accent);
    animation: blink 0.7s infinite;
}

@keyframes blink {
    0%, 100% { opacity: 1; }
    50% { opacity: 0; }
}

/* ==================== MODAL ==================== */
.modal-overlay {
    position: fixed;
    inset: 0;
    background: rgba(0, 0, 0, 0.8);
    backdrop-filter: blur(5px);
    display: flex;
    align-items: center;
    justify-content: center;
    z-index: 100;
    padding: var(--spacing-md);
}

.modal-content {
    background: var(--bg-medium);
    border: 1px solid var(--glass-border);
    border-radius: var(--radius-lg);
    padding: var(--spacing-lg);
    max-width: 340px;
    width: 100%;
}

/* ==================== COUNTDOWN OVERLAY ==================== */
#countdown-overlay {
    position: fixed;
    inset: 0;
    background: rgba(0, 0, 0, 0.95);
    display: flex;
    align-items: center;
    justify-content: center;
    z-index: 200;
}

.countdown-number {
    font-size: 8rem;
    font-weight: 800;
    font-family: 'JetBrains Mono', monospace;
    animation: countdownPop 0.5s ease-out;
}

@keyframes countdownPop {
    0% { transform: scale(0.5); opacity: 0; }
    50% { transform: scale(1.2); }
    100% { transform: scale(1); opacity: 1; }
}

/* ==================== CONFETTI ==================== */
.confetti-container {
    position: fixed;
    inset: 0;
    pointer-events: none;
    overflow: hidden;
    z-index: 1000;
}

.confetti {
    position: absolute;
    width: 10px;
    height: 10px;
    animation: confettiFall 3s ease-out forwards;
}

@keyframes confettiFall {
    0% { transform: translateY(-100%) rotate(0deg); opacity: 1; }
    100% { transform: translateY(100vh) rotate(720deg); opacity: 0; }
}

/* ==================== SPINNER ==================== */
.spinner {
    width: 40px;
    height: 40px;
    border: 3px solid var(--glass-border);
    border-top-color: var(--accent);
    border-radius: 50%;
    animation: spin 1s linear infinite;
}

@keyframes spin {
    to { transform: rotate(360deg); }
}

/* Terminal line fade-in */
.terminal-line {
    animation: lineAppear 0.3s ease-out;
}

@keyframes lineAppear {
    from {
        opacity: 0;
        transform: translateX(-10px);
    }
    to {
        opacity: 1;
        transform: translateX(0);
    }
}

/* ==================== SCROLLBAR ==================== */
::-webkit-scrollbar {
    width: 4px;
}

::-webkit-scrollbar-track {
    background: transparent;
}

::-webkit-scrollbar-thumb {
    background: rgba(255, 255, 255, 0.2);
    border-radius: 2px;
}

/* ==================== RESPONSIVE ==================== */
@media (max-height: 700px) {
    :root {
        --spacing-sm: 0.75rem;
        --spacing-md: 1rem;
        --spacing-lg: 1.5rem;
    }
    
    .text-3xl { font-size: 1.5rem; }
