        --spacing-md: 0.75rem;
        --spacing-lg: 1rem;
    }
    
    .btn {
        min-height: 44px;
        padding: 0.5rem 1rem;
    }
    
    .input {
        min-height: 44px;
        padding: 0.5rem 1rem;
    }
}

/* ==================== HIDDEN UTILITY ==================== */
.hidden {
    display: none !important;
}

/* ==================== EVIDENCE ITEMS ==================== */
.evidence-item {
    display: flex;
    align-items: center;
    gap: 0.5rem;
    padding: 0.5rem;
    background: rgba(16, 185, 129, 0.1);
    border-radius: var(--radius-sm);
    font-size: 0.875rem;
    margin-bottom: 0.5rem;
}

.evidence-item:last-child {
    margin-bottom: 0;
}

