            photoInput.click();
        });
    }
    
    if (uploadPhotoBtn && photoInput) {
        uploadPhotoBtn.addEventListener('click', () => {
            photoInput.removeAttribute('capture');
            photoInput.click();
        });
    }
    
    if (photoInput) {
