function applyPenalty(type) {
    const inMercyMode = gameState.investigationTimeLeft < 300; // < 5 minutes
    let penalty = 0;
    
    switch (type) {
        case 'secondWrong':
            penalty = inMercyMode ? 5 : CONFIG.PENALTIES.SECOND_WRONG;
