        case 'thirdWrong':
            penalty = inMercyMode ? 10 : CONFIG.PENALTIES.THIRD_WRONG;
            break;
        case 'hint':
            penalty = CONFIG.PENALTIES.HINT_COST;
            break;
        case 'skip':
            penalty = CONFIG.PENALTIES.SKIP_COST;
