    const shuffled = [...nonCaptains].sort(() => Math.random() - 0.5);
    
    const team1 = [CONFIG.PLAYERS.find(p => p.name === 'Mitch')];
    const team2 = [CONFIG.PLAYERS.find(p => p.name === 'Melisa')];
    
    // Alternate picks
    shuffled.forEach((player, index) => {
        if (index % 2 === 0) {
            team1.push(player);
        } else {
            team2.push(player);
        }
    });
    
    return { team1, team2 };
