        const allPicks = [];
        
        // Captains first
        allPicks.push({ player: teams.team1[0], team: 1 });
        allPicks.push({ player: teams.team2[0], team: 2 });
        
        // Alternate remaining
        for (let i = 1; i < teams.team1.length; i++) {
            allPicks.push({ player: teams.team1[i], team: 1 });
            if (teams.team2[i]) {
                allPicks.push({ player: teams.team2[i], team: 2 });
