    if (gameState.recentAttempts.length === 0) return 0;
    const oldest = Math.min(...gameState.recentAttempts);
    const cooldownEnd = oldest + CONFIG.RATE_LIMIT.WINDOW * 1000;
    return Math.max(0, Math.ceil((cooldownEnd - Date.now()) / 1000));
}

