        case 'hint':
            penalty = CONFIG.PENALTIES.HINT_COST;
            break;
        case 'skip':
            penalty = CONFIG.PENALTIES.SKIP_COST;
            break;
    }
    
    gameState.investigationTimeLeft = Math.max(0, gameState.investigationTimeLeft - penalty);
    
    // Show penalty animation
