    else if (timeLeft > 20 * 60) bonus = 1.75; // > 20 min = 1.75x
    else if (timeLeft > 10 * 60) bonus = 1.5; // > 10 min = 1.5x
    else if (timeLeft > 5 * 60) bonus = 1.25; // > 5 min = 1.25x
    
    if (isPerfect) bonus += 0.5; // Perfect run bonus
