    showVictoryStats,
    createConfetti,
    setupEventListeners,
    handleAnswerSubmit
};

// Global exports
window.showScreen = showScreen;
window.setupEventListeners = setupEventListeners;
window.updateInvestigationUI = updateInvestigationUI;
window.showVictoryScreen = showVictoryScreen;

