    const { gameState, checkAgainstAllUnsolved, recordAttempt, advancePhase, getUnsolvedPuzzles, PUZZLES, saveState } = window.GameEngine;
    
    // Generic handler that checks against ALL unsolved Phase 2 puzzles
    const handleTripleSubmit = (input, feedback) => {
        const answer = input.value.trim();
        if (!answer) return;
        
