        // Check against all unsolved Phase 2 puzzles
        const result = checkAgainstAllUnsolved(answer);
        
        if (result.valid) {
            gameState.solvedPuzzles.push(result.puzzleId);
            saveState();
            playSound('correct');
            
            const puzzle = PUZZLES[result.puzzleId];
            if (puzzle.thiefReaction) {
