            // Offer skip after 10 attempts
            if (attemptCount >= 10) {
                showSkipOffer();
            }
            
        } else {
            // First wrong - just a taunt
            showAnswerFeedback('wrong', taunt);
        }
    }
    
    input.value = '';
    input.focus();
