            const children = Array.from(terminalContent.children);
            children.forEach(child => {
                if (!child.contains(messageContainer) && child !== messageContainer) {
                    child.remove();
                }
            });
        }
        
        currentMessageIndex++;
        showThiefIntroMessage(messageContainer, beginButton);
